def structure():
    bundles, ordinal = [], 0
    for bid, bname, rationale, layers in ROWS:
        rendered = []
        for lid, lname, refs, items in layers:
            findings = []
            for item in items:
                ordinal += 1
                findings.append(finding(item, ordinal, refs))
            rendered.append({"id": lid, "name": lname, "description": f"Groups source-qualified sales-pursuit context for {lname.lower()}.", "source_refs": refs, "findings": findings})
        bundles.append({"id": bid, "name": bname, "description": f"Groups sales-pursuit context for {bname.lower()}.", "rationale": rationale, "source_refs": sorted({ref for layer in rendered for ref in layer["source_refs"]}), "layers": rendered})
    return {"bundles": bundles}


